#!/usr/bin/env node
/**
 * scripts/atlas/index-task-distillates-qdrant.mjs
 *
 * Creates the task_distillates collection in Qdrant and indexes
 * the task cards generated by build-task-distillates.mjs.
 */

import { readFileSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';
import { qdrantEnsureCollection, qdrantUpsertPoints, getQdrantUrl } from '../qdrant-client.mjs';

const QDRANT_URL = getQdrantUrl();
const OLLAMA_URL = process.env.OLLAMA_URL || 'http://127.0.0.1:11434';
const COLLECTION_NAME = 'task_distillates';
const DISTILLATES_FILE = resolve(process.cwd(), 'tmp/task-distillates.json');

async function getEmbedding(text) {
  const res = await fetch(`${OLLAMA_URL}/api/embeddings`, {
    method: 'POST',
    body: JSON.stringify({
      model: 'embeddinggemma:latest',
      prompt: text
    })
  });
  const data = await res.json();
  return data.embedding;
}

async function main() {
  console.log(`🚀 Atlas: Indexing Task Distillates to Qdrant (${COLLECTION_NAME})`);

  if (!existsSync(DISTILLATES_FILE)) {
    console.error(`❌ Distillates file not found: ${DISTILLATES_FILE}`);
    process.exit(1);
  }

  const distillates = JSON.parse(readFileSync(DISTILLATES_FILE, 'utf-8'));
  console.log(`📦 Loaded ${distillates.length} tasks.`);

  // 1. Ensure collection exists
  console.log(`🛠️  Ensuring collection ${COLLECTION_NAME}...`);
  await qdrantEnsureCollection(COLLECTION_NAME, 768).catch((err) =>
    console.warn('⚠️ ensureCollection failed', err?.message || err)
  );

  // 2. Index points
  const points = [];
  for (let i = 0; i < distillates.length; i++) {
    const task = distillates[i];
    console.log(`   [${i + 1}/${distillates.length}] Embedding: ${task.task_key}`);

    // Embed the summary for vector search
    const vector = await getEmbedding(task.summary);

    points.push({
      id: i + 1, // Simple incremental ID for tasks
      vector,
      payload: {
        ...task,
        source: 'atlas_distillate',
      },
    });
  }

  console.log(`📤 Uploading ${points.length} points to Qdrant...`);
  const ok = await qdrantUpsertPoints(COLLECTION_NAME, points);
  if (ok) {
    console.log('✅ Task distillates indexed successfully.');
  } else {
    console.error('❌ Failed to index tasks.');
  }
}

main().catch(err => {
  console.error(`❌ Error: ${err.message}`);
  process.exit(1);
});
